@startuml
abstract class Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class BasicContract extends Contract {
  + contractNumber : int
  + balance : double
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

abstract class ContractOption extends Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class DataOption extends ContractOption {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class SmsOption extends ContractOption {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class MinutesOption extends ContractOption {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class DoubleTransferRateOption extends ContractOption {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

Contract "0..*" -- "0..1" ContractOption : decorates
@enduml

